    38  /*!
    39   * Each layer in an XCF file is stored as a matrix of
    40   * 64-pixel by 64-pixel images. The GIMP has a sophisticated
    41   * method of handling very large images as well as implementing
    42   * parallel processing on a tile-by-tile basis. Here, though,
    43   * we just read them in en-masse and store them in a matrix.
    44   */
    45  typedef QVector<QVector<QImage> > Tiles;
