   892  /*!
   893   * Copy the bytes from the tile buffer into the image tile QImage, taking into
   894   * account all the myriad different modes.
   895   * \param layer layer containing the tile buffer and the image tile matrix.
   896   * \param i column index of current tile.
   897   * \param j row index of current tile.
   898   */
   899  void XCFImageFormat::assignImageBytes(Layer &layer, uint i, uint j)
   900  {
   901      QImage &image = layer.image_tiles[j][i];
   902      uchar *tile = layer.tile;
   903      const int width = image.width();
   904      const int height = image.height();
   905      const int bytesPerLine = image.bytesPerLine();
   906      uchar *bits = image.bits();
   907
   908      switch (layer.type) {
   909      case RGB_GIMAGE:
   910          for (int y = 0; y < height; y++) {
   911              QRgb *dataPtr = (QRgb *)(bits + y * bytesPerLine);
   912              for (int x = 0; x < width; x++) {
   913                  *dataPtr++ = qRgb(tile[0], tile[1], tile[2]);
   914                  tile += sizeof(QRgb);
   915              }
   916          }
   917          break;
   918
   919      case RGBA_GIMAGE:
   920          for (int y = 0; y < height; y++) {
   921              QRgb *dataPtr = (QRgb *)(bits + y * bytesPerLine);
   922              for (int x = 0; x < width; x++) {
   923                  *dataPtr++ =    qRgba(tile[0], tile[1], tile[2], tile[3]);
   924                  tile += sizeof(QRgb);
   925              }
   926          }
   927          break;
   928
   929      case GRAY_GIMAGE:
   930      case INDEXED_GIMAGE:
   931          for (int y = 0; y < height; y++) {
   932              uchar *dataPtr = bits + y * bytesPerLine;
   933              for (int x = 0; x < width; x++) {
   934                  *dataPtr++ = tile[0];
   935                  tile += sizeof(QRgb);
   936              }
   937          }
   938          break;
   939
   940      case GRAYA_GIMAGE:
   941      case INDEXEDA_GIMAGE:
   942          for (int y = 0; y < height; y++) {
   943              uchar *dataPtr = bits + y * bytesPerLine;
   944              uchar *alphaPtr = layer.alpha_tiles[j][i].scanLine(y);
   945              for (int x = 0; x < width; x++) {
   946
   947                  // The "if" here should not be necessary, but apparently there
   948                  // are some cases where the image can contain larger indices
   949                  // than there are colors in the palette. (A bug in The GIMP?)
   950
   951                  if (tile[0] < image.colorCount()) {
   952                      *dataPtr = tile[0];
   953                  }
   954
   955                  *alphaPtr = tile[1];
   956                  dataPtr += 1;
   957                  alphaPtr += 1;
   958                  tile += sizeof(QRgb);
   959              }
   960          }
   961          break;
   962      }
   963  }
