   965  /*!
   966   * The GIMP stores images in a "mipmap"-like hierarchy. As far as the QImage
   967   * is concerned, however, only the top level (i.e., the full resolution image)
   968   * is used.
   969   * \param xcf_io the data stream connected to the XCF image.
   970   * \param layer the layer to collect the image.
   971   * \return true if there were no I/O errors.
   972   */
   973  bool XCFImageFormat::loadHierarchy(QDataStream &xcf_io, Layer &layer)
   974  {
   975      qint32 width;
   976      qint32 height;
   977      qint32 bpp;
   978      quint32 offset;
   979
   980      xcf_io >> width >> height >> bpp >> offset;
   981
   982      // make sure bpp is correct and complain if it is not
   983      switch (layer.type) {
   984          case RGB_GIMAGE:
   985              if (bpp != 3) {
   986                  qWarning() << "Found layer of type RGB but with bpp != 3" << bpp;
   987                  bpp = 3;
   988              }
   989              break;
   990          case RGBA_GIMAGE:
   991              if (bpp != 4) {
   992                  qWarning() << "Found layer of type RGBA but with bpp != 4" << bpp;
   993                  bpp = 4;
   994              }
   995              break;
   996          case GRAY_GIMAGE:
   997              if (bpp != 1) {
   998                  qWarning() << "Found layer of type Gray but with bpp != 1" << bpp;
   999                  bpp = 1;
  1000              }
  1001              break;
  1002          case GRAYA_GIMAGE:
  1003              if (bpp != 2) {
  1004                  qWarning() << "Found layer of type Gray+Alpha but with bpp != 2" << bpp;
  1005                  bpp = 2;
  1006              }
  1007              break;
  1008          case INDEXED_GIMAGE:
  1009              if (bpp != 1) {
  1010                  qWarning() << "Found layer of type Indexed but with bpp != 1" << bpp;
  1011                  bpp = 1;
  1012              }
  1013              break;
  1014          case INDEXEDA_GIMAGE:
  1015              if (bpp != 2) {
  1016                  qWarning() << "Found layer of type Indexed+Alpha but with bpp != 2" << bpp;
  1017                  bpp = 2;
  1018              }
  1019              break;
  1020      }
  1021
  1022      // GIMP stores images in a "mipmap"-like format (multiple levels of
  1023      // increasingly lower resolution). Only the top level is used here,
  1024      // however.
  1025
  1026      quint32 junk;
  1027      do {
  1028          xcf_io >> junk;
  1029
  1030          if (xcf_io.device()->atEnd()) {
  1031  //          qDebug() << "XCF: read failure on layer " << layer.name << " level offsets";
  1032              return false;
  1033          }
  1034      } while (junk != 0);
  1035
  1036      qint64 saved_pos = xcf_io.device()->pos();
  1037
  1038      xcf_io.device()->seek(offset);
  1039      if (!loadLevel(xcf_io, layer, bpp)) {
  1040          return false;
  1041      }
  1042
  1043      xcf_io.device()->seek(saved_pos);
  1044      return true;
  1045  }
  1162  bool XCFImageFormat::loadTileRLE(QDataStream &xcf_io, uchar *tile, int image_size,
  1163                                   int data_length, qint32 bpp)
  1164  {
  1165      uchar *data;
  1166
  1167      uchar *xcfdata;
  1168      uchar *xcfodata;
  1169      uchar *xcfdatalimit;
  1170
  1171      if (data_length < 0 || data_length > int(TILE_WIDTH * TILE_HEIGHT * 4 * 1.5)) {
  1172  //      qDebug() << "XCF: invalid tile data length" << data_length;
  1173          return false;
  1174      }
  1175
  1176      xcfdata = xcfodata = new uchar[data_length];
  1177
  1178      const int dataRead = xcf_io.readRawData((char *)xcfdata, data_length);
  1179      if (dataRead < data_length) {
  1180  //      qDebug() << "XCF: read less data than expected" << data_length << dataRead;
  1181          memset(&xcfdata[dataRead], 0, data_length - dataRead);
  1182      }
  1183
  1184      if (!xcf_io.device()->isOpen()) {
  1185          delete[] xcfodata;
  1186  //      qDebug() << "XCF: read failure on tile";
  1187          return false;
  1188      }
  1189
  1190      xcfdatalimit = &xcfodata[data_length - 1];
  1191
  1192      for (int i = 0; i < bpp; ++i) {
  1193
  1194          data = tile + i;
  1195
  1196          int count = 0;
  1197          int size = image_size;
  1198
  1199          while (size > 0) {
  1200              if (xcfdata > xcfdatalimit) {
  1201                  goto bogus_rle;
  1202              }
  1203
  1204              uchar val = *xcfdata++;
  1205              uint length = val;
  1206
  1207              if (length >= 128) {
  1208                  length = 255 - (length - 1);
  1209                  if (length == 128) {
  1210                      if (xcfdata >= xcfdatalimit) {
  1211                          goto bogus_rle;
  1212                      }
  1213
  1214                      length = (*xcfdata << 8) + xcfdata[1];
  1215
  1216                      xcfdata += 2;
  1217                  }
  1218
  1219                  count += length;
  1220                  size -= length;
  1221
  1222                  if (size < 0) {
  1223                      goto bogus_rle;
  1224                  }
  1225
  1226                  if (&xcfdata[length - 1] > xcfdatalimit) {
  1227                      goto bogus_rle;
  1228                  }
  1229
  1230                  while (length-- > 0) {
  1231                      *data = *xcfdata++;
  1232                      data += sizeof(QRgb);
  1233                  }
  1234              } else {
  1235                  length += 1;
  1236                  if (length == 128) {
  1237                      if (xcfdata >= xcfdatalimit) {
  1238                          goto bogus_rle;
  1239                      }
  1240
  1241                      length = (*xcfdata << 8) + xcfdata[1];
  1242                      xcfdata += 2;
  1243                  }
  1244
  1245                  count += length;
  1246                  size -= length;
  1247
  1248                  if (size < 0) {
  1249                      goto bogus_rle;
  1250                  }
  1251
  1252                  if (xcfdata > xcfdatalimit) {
  1253                      goto bogus_rle;
  1254                  }
  1255
  1256                  val = *xcfdata++;
  1257
  1258                  while (length-- > 0) {
  1259                      *data = val;
  1260                      data += sizeof(QRgb);
  1261                  }
  1262              }
  1263          }
  1264      }
  1265
  1266      delete[] xcfodata;
  1267      return true;
  1268
  1269  bogus_rle:
  1270
  1271  //  qDebug() << "The run length encoding could not be decoded properly";
  1272      delete[] xcfodata;
  1273      return false;
  1274  }
