  1799  /*!
  1800   * Merge a layer into an image, taking account of the manifold modes.
  1801   * \param xcf_image contains the layer and image to merge.
  1802   */
  1803  void XCFImageFormat::mergeLayerIntoImage(XCFImage &xcf_image)
  1804  {
  1805      Layer &layer(xcf_image.layer);
  1806      QImage &image(xcf_image.image);
  1807
  1808      PixelMergeOperation merge = nullptr;
  1809
  1810      if (!layer.opacity) {
  1811          return;    // don't bother doing anything
  1812      }
  1813
  1814      switch (layer.type) {
  1815      case RGB_GIMAGE:
  1816      case RGBA_GIMAGE:
  1817          merge = mergeRGBToRGB;
  1818          break;
  1819      case GRAY_GIMAGE:
  1820          if (layer.opacity == OPAQUE_OPACITY) {
  1821              merge = mergeGrayToGray;
  1822          } else {
  1823              merge = mergeGrayToRGB;
  1824          }
  1825          break;
  1826      case GRAYA_GIMAGE:
  1827          if (xcf_image.image.depth() <= 8) {
  1828              merge = mergeGrayAToGray;
  1829          } else {
  1830              merge = mergeGrayAToRGB;
  1831          }
  1832          break;
  1833      case INDEXED_GIMAGE:
  1834          merge = mergeIndexedToIndexed;
  1835          break;
  1836      case INDEXEDA_GIMAGE:
  1837          if (xcf_image.image.depth() <= 8) {
  1838              merge = mergeIndexedAToIndexed;
  1839          } else {
  1840              merge = mergeIndexedAToRGB;
  1841          }
  1842      }
  1843
  1844      if (!merge) {
  1845          return;
  1846      }
  1847
  1848      for (uint j = 0; j < layer.nrows; j++) {
  1849          uint y = j * TILE_HEIGHT;
  1850
  1851          for (uint i = 0; i < layer.ncols; i++) {
  1852              uint x = i * TILE_WIDTH;
  1853
  1854              // This seems the best place to apply the dissolve because it
  1855              // depends on the global position of each tile's
  1856              // pixels. Apparently it's the only mode which can apply to a
  1857              // single layer.
  1858
  1859              if (layer.mode == DISSOLVE_MODE) {
  1860                  if (!random_table_initialized) {
  1861                      initializeRandomTable();
  1862                      random_table_initialized = true;
  1863                  }
  1864                  if (layer.type == RGBA_GIMAGE) {
  1865                      dissolveRGBPixels(layer.image_tiles[j][i], x, y);
  1866                  }
  1867
  1868                  else if (layer.type == GRAYA_GIMAGE) {
  1869                      dissolveAlphaPixels(layer.alpha_tiles[j][i], x, y);
  1870                  }
  1871              }
  1872
  1873              // Shortcut for common case
  1874              if (merge == mergeRGBToRGB && layer.apply_mask != 1
  1875                      && layer.mode == NORMAL_MODE) {
  1876                  QPainter painter(&image);
  1877                  painter.setOpacity(layer.opacity / 255.0);
  1878                  painter.setCompositionMode(QPainter::CompositionMode_SourceOver);
  1879                  painter.drawImage(x + layer.x_offset, y + layer.y_offset, layer.image_tiles[j][i]);
  1880                  continue;
  1881              }
  1882
  1883              for (int l = 0; l < layer.image_tiles[j][i].height(); l++) {
  1884                  for (int k = 0; k < layer.image_tiles[j][i].width(); k++) {
  1885
  1886                      int m = x + k + layer.x_offset;
  1887                      int n = y + l + layer.y_offset;
  1888
  1889                      if (m < 0 || m >= image.width() || n < 0 || n >= image.height()) {
  1890                          continue;
  1891                      }
  1892
  1893                      (*merge)(layer, i, j, k, l, image, m, n);
  1894                  }
  1895              }
  1896          }
  1897      }
  1898  }
