  1900  /*!
  1901   * Merge an RGB pixel from the layer to the RGB image. Straight-forward.
  1902   * The only thing this has to take account of is the opacity of the
  1903   * layer. Evidently, the GIMP exporter itself does not actually do this.
  1904   * \param layer source layer.
  1905   * \param i x tile index.
  1906   * \param j y tile index.
  1907   * \param k x pixel index of tile i,j.
  1908   * \param l y pixel index of tile i,j.
  1909   * \param image destination image.
  1910   * \param m x pixel of destination image.
  1911   * \param n y pixel of destination image.
  1912   */
  1913  void XCFImageFormat::mergeRGBToRGB(Layer &layer, uint i, uint j, int k, int l,
  1914                                     QImage &image, int m, int n)
  1915  {
  1916      QRgb src = layer.image_tiles[j][i].pixel(k, l);
  1917      QRgb dst = image.pixel(m, n);
  1918
  1919      uchar src_r = qRed(src);
  1920      uchar src_g = qGreen(src);
  1921      uchar src_b = qBlue(src);
  1922      uchar src_a = qAlpha(src);
  1923
  1924      uchar dst_r = qRed(dst);
  1925      uchar dst_g = qGreen(dst);
